cronAdd('i7y-operation-tickets','*/5 * * * *',()=>{for(const r of $app.findRecordsByFilter('operation_tickets','consumed=false && expires_at < {:cutoff}','',500,0,{cutoff:new Date(Date.now()-86400000).toISOString()}))$app.delete(r)})
